// 解析Grove Vision AI V2的输出
const payload = msg.payload;
const topic = msg.topic;
const deviceId = topic.split('/')[2];

// 验证数据格式
if (!payload.bboxes || !Array.isArray(payload.bboxes) || payload.bboxes.length === 0) {
    node.warn('No face detected in frame');
    return null;
}

// 选择最大面积的人脸
let maxBbox = null;
let maxArea = 0;

for (const bbox of payload.bboxes) {
    const area = bbox.w * bbox.h;
    if (area > maxArea && bbox.score > 0.7) {
        maxArea = area;
        maxBbox = bbox;
    }
}

if (!maxBbox) {
    node.warn('No valid face bbox found');
    return null;
}

// 准备FaceEmbed API请求
msg.deviceId = deviceId;
msg.originalPayload = payload;
msg.payload = {
    image_base64: payload.img_b64,
    bbox: {
        x: Math.round(maxBbox.x),
        y: Math.round(maxBbox.y),
        w: Math.round(maxBbox.w),
        h: Math.round(maxBbox.h)
    }
};

return msg;

// 获取人脸向量
const embedding = msg.payload.vector;
const confidence = msg.payload.confidence;
const processingTime = msg.payload.processing_time_ms;

// 检查向量质量
if (confidence < 0.5) {
    node.warn(`Low face quality: ${confidence}`);
    return null;
}

// 获取设备配置
const deviceId = msg.deviceId;
const collectionName = env.get(`COLLECTION_${deviceId}`) || 'default_faces';
const threshold = parseFloat(env.get('SIMILARITY_THRESHOLD') || '0.32');

// 准备Qdrant搜索请求
msg.collectionName = collectionName;
msg.threshold = threshold;
msg.embedding = embedding;
msg.confidence = confidence;
msg.processingTime = processingTime;

// Qdrant向量搜索请求URL (支持远程部署)
const qdrantHost = env.get('QDRANT_HOST') || 'localhost';
const qdrantPort = env.get('QDRANT_PORT') || '6333';
msg.url = `http://${qdrantHost}:${qdrantPort}/collections/${collectionName}/points/search`;
msg.payload = {
    vector: embedding,
    limit: 3,
    with_payload: true,
    score_threshold: 1 - threshold  // Qdrant使用余弦相似度，需要转换阈值
};

return msg;

const searchResult = msg.payload.result;
const deviceId = msg.deviceId;
const threshold = msg.threshold;
const timestamp = new Date().toISOString();

let decision = false;
let name = null;
let distance = 1.0;
let matchedId = null;

// 检查搜索结果
if (searchResult && searchResult.length > 0) {
    const bestMatch = searchResult[0];
    distance = 1 - bestMatch.score;  // 转换为距离

    if (distance <= threshold) {
        decision = true;
        name = bestMatch.payload.name;
        matchedId = bestMatch.id;
    }
}

// 构造结果消息
const result = {
    ts: timestamp,
    device_id: deviceId,
    decision: decision,
    name: name,
    distance: parseFloat(distance.toFixed(4)),
    confidence: msg.confidence,
    processing_time_ms: msg.processingTime,
    matched_id: matchedId
};

// 准备MQTT发布
msg.topic = `access/result/${deviceId}`;
msg.payload = result;

// 保存到context用于日志记录
context.set('lastAccess', result);

return msg;

const result = msg.payload;

// 记录访问日志
node.log(`Access Decision - Device: ${result.device_id}, Decision: ${result.decision}, Name: ${result.name || 'Unknown'}, Distance: ${result.distance}`);

// 可以在这里添加更详细的日志记录逻辑
// 例如写入文件、数据库或发送到监控系统

return msg;

const payload = msg.payload;
const topic = msg.topic;
const deviceId = topic.split('/')[2];

// 验证入库请求
if (!payload.name || !payload.action) {
    node.error('Invalid enroll request: missing name or action');
    return null;
}

if (payload.action === 'start') {
    // 开始入库流程
    msg.deviceId = deviceId;
    msg.enrollName = payload.name;
    msg.payload = {
        action: 'start_collection',
        name: payload.name,
        device_id: deviceId
    };

    // 设置入库状态
    context.set(`enroll_${deviceId}`, {
        name: payload.name,
        status: 'collecting',
        frames: [],
        startTime: Date.now()
    });

    return msg;
}

return null;

// 这个节点会监听后续的vision帧来收集人脸数据
// 实际实现中需要与vision_frame_processor协调

const deviceId = msg.deviceId;
const enrollState = context.get(`enroll_${deviceId}`);

if (!enrollState || enrollState.status !== 'collecting') {
    return null;
}

// 发送开始收集的指令
msg.topic = `access/enroll_status/${deviceId}`;
msg.payload = {
    status: 'collecting',
    message: `开始收集 ${enrollState.name} 的人脸数据，请保持正面朝向摄像头`,
    frames_needed: 10
};

return msg;

// 支持批量人脸处理以提高并发性能
const frameQueue = context.get('frameQueue') || [];
const batchSize = parseInt(env.get('BATCH_SIZE') || '3');
const maxWaitTime = parseInt(env.get('MAX_WAIT_TIME') || '100'); // ms

// 添加当前帧到队列
frameQueue.push({
    deviceId: msg.deviceId,
    payload: msg.payload,
    timestamp: Date.now()
});

// 检查是否需要批量处理
if (frameQueue.length >= batchSize || 
    (frameQueue.length > 0 && (Date.now() - frameQueue[0].timestamp) > maxWaitTime)) {

    // 准备批量请求
    const batchFrames = frameQueue.splice(0, batchSize);
    context.set('frameQueue', frameQueue);

    // 构造批量API请求
    const faceEmbedHost = env.get('FACE_EMBED_API_HOST') || '192.168.10.179';
    const faceEmbedPort = env.get('FACE_EMBED_API_PORT') || '8000';

    msg.url = `http://${faceEmbedHost}:${faceEmbedPort}/batch_embed`;
    msg.payload = {
        images: batchFrames.map(frame => frame.payload)
    };
    msg.batchFrames = batchFrames;

    return msg;
} else {
    // 更新队列
    context.set('frameQueue', frameQueue);
    return null;
}

// 将批量结果分发给各个设备
const batchResults = msg.payload;
const batchFrames = msg.batchFrames;

if (!batchResults.vectors || batchResults.vectors.length !== batchFrames.length) {
    node.error('Batch processing result mismatch');
    return null;
}

const messages = [];

// 为每个设备创建单独的消息
for (let i = 0; i < batchFrames.length; i++) {
    const frame = batchFrames[i];
    const result = {
        vector: batchResults.vectors[i],
        processing_time_ms: batchResults.processing_times[i],
        confidence: 0.8 // 批量处理时使用默认置信度
    };

    messages.push({
        deviceId: frame.deviceId,
        payload: result,
        timestamp: frame.timestamp
    });
}

// 返回多个消息
return [messages];

// 生成系统心跳信息
const faceEmbedHost = env.get('FACE_EMBED_API_HOST') || '192.168.10.179';
const faceEmbedPort = env.get('FACE_EMBED_API_PORT') || '8000';

const heartbeat = {
    timestamp: new Date().toISOString(),
    service: 'face_access_control',
    version: '1.0.0',
    status: 'running',
    uptime: process.uptime(),
    memory_usage: process.memoryUsage(),
    config: {
        face_embed_api: `${faceEmbedHost}:${faceEmbedPort}`,
        qdrant_host: env.get('QDRANT_HOST') || 'localhost',
        similarity_threshold: env.get('SIMILARITY_THRESHOLD') || '0.32'
    },
    last_access: context.get('lastAccess') || null,
    frame_queue_size: (context.get('frameQueue') || []).length
};

msg.payload = heartbeat;
return msg;

// 动态配置FaceEmbed API URL
const faceEmbedHost = env.get('FACE_EMBED_API_HOST') || '192.168.10.179';
const faceEmbedPort = env.get('FACE_EMBED_API_PORT') || '8000';

// 设置API URL
msg.url = `http://${faceEmbedHost}:${faceEmbedPort}/embed`;

// 添加超时配置
msg.timeout = parseInt(env.get('API_TIMEOUT') || '5000'); // 5秒超时

return msg;
